class FuelRod(val id: Int, val level: Int) {
    fun decreaseLevel(amount: Int) {
        level -= amount
        if (level < 0) {
            level = 0
        }
    }
}

// Define a class to represent the reactor
class Reactor {
    private val fuelRodCount: AtomicInteger = AtomicInteger(0)
    private val fuelRodLevels: MutableList<FuelRod> = mutableListOf()

    fun addFuelRod(id: Int, level: Int) {
        fuelRodLevels.add(FuelRod(id, level))
        fuelRodCount.incrementAndGet()
    }

    fun decreaseFuelRodLevel(id: Int, amount: Int) {
        val fuelRod = fuelRodLevels.find { it.id == id }
        if (fuelRod != null) {
            fuelRod.decreaseLevel(amount)
        }
    }

    fun getFuelRodLevel(id: Int): Int {
        val fuelRod = fuelRodLevels.find { it.id == id }
        return if (fuelRod != null) fuelRod.level else 0
    }

    fun getFuelRodCount(): Int {
        return fuelRodCount.get()
    }
}

// Define a function to simulate the reactor's actions
suspend fun simulateReactorActions(reactor: Reactor, actions: List<Pair<Int, Int>>): Int {
    var fuelRodLevel = reactor.getFuelRodLevel(0)
    for ((id, amount) in actions) {
        reactor.decreaseFuelRodLevel(id, amount)
        fuelRodLevel = reactor.getFuelRodLevel(0)
    }
    return fuelRodLevel
}

// Define a function to orchestrate the actions
