        val fuelRodLevel = simulateReactorActions(reactor, actions)
        reactor.fuelRodLevels.forEach { it.level = 0 } // reset fuel rod levels
        reactor.fuelRodCount.set(0) // reset fuel rod count
        return fuelRodLevel
    }
}

